pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Restrict inputs to realistic ranges
        vm.assume(depositAmount > 0 && depositAmount <= type(uint200).max);
        vm.assume(collectAmount > 0 && collectAmount <= type(uint200).max);
        vm.assume(minSum <= type(uint200).max);

        // Setup: set initial parameters
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit funds for the caller
        address(c).call{value: depositAmount}("");

        // Record total sum of all balances before Collect
        uint256 sumBefore = c.balances(caller);

        // Call Collect
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Only check property if the call didn't revert
        if (success) {
            uint256 sumAfter = c.balances(caller);
            // The total balances sum should not change (conservation)
            // Since we only have one depositor, sumBefore == balances(caller) before
            // and sumAfter == balances(caller) after
            assertTrue(sumAfter + (success ? collectAmount : 0) == sumBefore + depositAmount);
        }
    }
}

