pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _am, address _caller) public {
        vm.assume(_caller != address(0));
        _minSum = bound(_minSum, 0, 1e30);
        _am = bound(_am, 0, 1e30);

        // Initialize the contract
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller with enough balance
        uint256 depositAmount = _am + 1e18;
        vm.deal(_caller, depositAmount);
        vm.prank(_caller);
        c.Deposit{value: depositAmount}();

        // Try to collect _am
        vm.prank(_caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // After a successful Collect call, the caller's balance should be >= MinSum
        // (because Collect only proceeds if balance >= MinSum and then subtracts _am <= balance)
        uint256 callerBalance = c.balances(_caller);
        if (success) {
            assertTrue(callerBalance >= _minSum, "After successful Collect, caller balance should be >= MinSum");
        }
    }
}

