pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 depositAmount, uint256 collectAmount, address caller) public {
        // Restrict inputs so the reference can work: depositAmount must not overflow
        vm.assume(depositAmount <= type(uint256).max - 1);
        vm.assume(depositAmount > 0 || collectAmount == 0);

        // Setup: set MinSum and initialize
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The general rule: if Collect succeeded, then balanceBefore >= minSum and balanceBefore > collectAmount
        if (success) {
            assertTrue(balanceBefore >= minSum && balanceBefore > collectAmount, "Collect succeeded despite violating precondition");
        } else {
            // If it reverted, no assertion needed
            assertTrue(true);
        }
    }
}

