pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmt, uint256 minSum, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmt <= type(uint128).max);
        vm.assume(collectAmt <= depositAmt);
        vm.deal(caller, depositAmt);

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit from caller
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        uint256 balanceBefore = c.balances(caller);

        // Collect if conditions are satisfied
        if (balanceBefore >= minSum && balanceBefore >= collectAmt) {
            vm.prank(caller);
            (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));
            if (!ok) {
                // If it reverted, balance must be unchanged
                assertTrue(c.balances(caller) == balanceBefore);
            } else {
                // If successful, balance decreased by exactly collectAmt
                assertTrue(c.balances(caller) == balanceBefore - collectAmt);
            }
        }
    }
}

