pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(initialBalance <= 1e18 && depositAmount <= 1e18 && collectAmount <= 1e18);
        vm.assume(caller != address(0));

        // Setup: set MinSum to 0 and initialize so Collect is accessible
        c.SetMinSum(0);
        c.Initialized();

        // Fund the caller
        vm.deal(caller, initialBalance + depositAmount);

        // Deposit funds
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record sum of balances before Collect
        // We need to track all possible addresses - for simplicity we check caller's balance
        uint256 balanceBefore = c.balances(caller);

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        if (success) {
            uint256 balanceAfter = c.balances(caller);
            // The caller's balance should have decreased by exactly collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance change mismatch after Collect");
        } else {
            // If Collect reverted, the balance should remain unchanged
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore, "Balance changed despite revert");
        }
    }
}

