pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amountToCollect, uint256 minSum, uint256 initialBalance) public {
        // Ensure the caller is not address(0) to avoid send issues
        vm.assume(caller != address(0));
        // Bound inputs to reasonable ranges
        amountToCollect = bound(amountToCollect, 0, 1000000 ether);
        minSum = bound(minSum, 0, 1000000 ether);
        initialBalance = bound(initialBalance, 0, 1000000 ether);

        // Set up: fund caller, initialize contract
        vm.deal(caller, initialBalance + amountToCollect);
        vm.prank(caller);
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit initialBalance into contract for caller
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Get balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        bool success;
        {
            vm.prank(caller);
            (bool ok, bytes memory returnData) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amountToCollect));
            success = ok;
        }

        uint256 balanceAfter = c.balances(caller);

        // Rule: If Collect fails (caller's balance < MinSum or caller's balance < amountToCollect), then caller's balance must remain unchanged.
        if (!success) {
            assertTrue(balanceAfter == balanceBefore, "If Collect reverts, balance should stay same");
        } else {
            // If Collect succeeds, balance decreases by exactly amountToCollect
            assertTrue(balanceAfter == balanceBefore - amountToCollect, "If Collect succeeds, balance decreases by amount");
        }
    }
}

