pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 setMinSum) public {
        // Restrict depositAmount to avoid overflow and ensure it doesn't exceed caller's balance
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        // Restrict setMinSum so that MinSum <= depositAmount (so Collect can succeed)
        setMinSum = bound(setMinSum, 0, depositAmount);

        // Initialize contract: SetMinSum and SetLogFile (choose any address), then Initialized
        c.SetMinSum(setMinSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller with enough ETH for deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record caller's balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect with amount = 0 (minimum allowed)
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0));

        // Assert that after the call (whether it reverts or not), the balance hasn't changed
        // because Collect(0) should not transfer any ETH and the reference C should maintain balance
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceAfter == balanceBefore, "Balance changed after Collect(0)");
