        vm.assume(c.MinSum() <= _deposit);

        // Call Collect
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collect));

        // After Collect, MinSum must equal _val (the value set by SetMinSum)
        assertTrue(c.MinSum() == _val);
    }
