    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Bound deposit amount to avoid overflow
        depositAmount = bound(depositAmount, 1, 10000 ether);

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Get balance before collect
        uint256 balanceBefore = c.balances(caller);

        // Bound collect amount to be valid
        collectAmount = bound(collectAmount, 0, balanceBefore);

        // Perform collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Get balance after collect
        uint256 balanceAfter = c.balances(caller);

        if (success) {
            // If collect succeeded, balance should have decreased by the collected amount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collected amount");
        } else {
            // If collect failed, balance should stay the same
            assertTrue(balanceAfter == balanceBefore, "Balance should remain unchanged");
        }
    }
}

