import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 depositAmount, uint256 collectAmount) public {
        // Bound deposit and collect amounts to reasonable values
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 1, 1e18);

        // Initialize the contract
        c.SetMinSum(collectAmount);
        c.Initialized();

        // Deposit from user
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Record total contract balance before collect
        uint256 totalBefore = address(c).balance;

        // Call Collect
        vm.prank(user);
        c.Collect(collectAmount);

        // Rule: change in contract balance equals change in user's recorded balance
        uint256 userBalanceAfter = c.balances(user);
        uint256 totalAfter = address(c).balance;

        // The bug (setting balance instead of adding) breaks:
        // When bug is present, userBalanceAfter = collectAmount (since deposit set to msg.value, collect subtracts from that)
        // So totalAfter = depositAmount - collectAmount (if collect succeeds)
        // But in correct version: userBalanceAfter = depositAmount - collectAmount
        // Correct invariant: totalAfter + userBalanceAfter = depositAmount (the deposited amount stayed constant or decreased by collect)
        // Actually the correct invariant: totalAfter = depositAmount - collectAmount (since deposited amount goes to contract, then collect sends collectAmount out)
        // But bug means userBalanceAfter might be different...
        // Simpler: totalAfter + userBalanceAfter should equal depositAmount (if collect succeeds, sum of contract balance + user's balance = original deposit)
        assertTrue(totalAfter + userBalanceAfter <= depositAmount, "Invariant violated");
    }
}

