pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount < type(uint256).max / 2);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1)); // dummy log address
        c.Initialized();

        // Deposit from user
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Record state before Collect
        uint256 balanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.balances(user);

        // Call Collect (may revert if conditions not met)
        bool reverted = false;
        try c.Collect(collectAmount) {
            // success
        } catch {
            reverted = true;
        }

        // Rule: After Collect, the contract's ether balance equals the sum of all balances
        // plus (if Collect succeeded) the collected amount that is still in the contract before transfer
        // Actually, the invariant is: contract balance = sum of all balances (since Collect transfers ether out)
        // We can check this directly:
        uint256 sumBalances = c.balances(user); // only user has balance
        uint256 contractBalance = address(c).balance;

        assertTrue(contractBalance == sumBalances, "Contract balance should equal sum of user balances");
    }
}

