pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);

        // Initialize the contract: set MinSum to 0 (minimum withdrawal threshold)
        c.SetMinSum(0);
        // Set a dummy log file address (any non-zero address to avoid revert)
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Give caller funds and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        // Attempt withdrawal; the amount must be <= depositAmount and <= balances[caller]
        vm.assume(withdrawAmount <= depositAmount);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        uint256 balanceAfter = address(c).balance;

        // General rule: If Collect succeeded, the contract balance decreased by exactly withdrawAmount
        // If it reverted, the balance stayed the same (withdrawAmount == 0 would be impossible due to assume)
        if (success) {
            assertTrue(balanceBefore - balanceAfter == withdrawAmount, "Contract balance should decrease by withdraw amount");
        } else {
            assertTrue(balanceBefore == balanceAfter, "Contract balance should remain unchanged on revert");
        }
    }
}

