pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(withdrawAmount <= type(uint256).max);
        // Set MinSum to 0 so Collect can succeed
        c.SetMinSum(0);
        c.Initialized();
        // Fund the contract with some ETH and give caller zero balance (no deposit)
        vm.deal(address(c), 1 ether);
        // Call Collect with caller having zero balance — will succeed in reference (allow zero) but revert in buggy
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));
        // The general rule: if the deposit was zero (i.e., caller's balance hasn't increased), Collect should not revert; 
        // but buggy contract rejects zero deposits, so Collect reverts when caller's balance is zero even before any deposit.
        // Since caller's balance is 0, any non-zero withdraw will fail anyway due to insufficient balance; 
        // only withdrawAmount = 0 could succeed in reference but reverts in buggy.
        // We assert that for withdrawAmount = 0, the reference succeeds (true) while buggy fails.
        vm.assume(withdrawAmount == 0);
        assertTrue(success, "Withdraw of 0 should succeed");
    }
}

