pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 amt1, uint256 amt2, uint256 minSum, uint256 collectAmt) public {
        // Bound inputs to avoid unrealistic values
        amt1 = bound(amt1, 0.1 ether, 10 ether);
        amt2 = bound(amt2, 0.1 ether, 10 ether);
        minSum = bound(minSum, 0.1 ether, 5 ether);
        collectAmt = bound(collectAmt, 0, 5 ether);

        // Set min sum and initialize contract
        vm.assume(minSum > 0);
        c.SetMinSum(minSum);
        c.SetLogFile(address(0)); // dummy log
        c.Initialized();

        // Fund caller1 and deposit
        vm.deal(caller1, amt1);
        vm.prank(caller1);
        c.Deposit{value: amt1}();

        // Fund caller2 and deposit
        vm.deal(caller2, amt2);
        vm.prank(caller2);
        c.Deposit{value: amt2}();

        // Record balance before collect
        uint256 balanceBefore = address(c).balance;

        // Call collect from caller1
        vm.prank(caller1);
        uint256 bal1_before = c.balances(caller1);
        uint256 bal2_before = c.balances(caller2);
        bool collectSuccess = false;
        if (bal1_before >= minSum && bal1_before >= collectAmt) {
            (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
            collectSuccess = ok;
        } else {
            // If condition fails, Collect reverts — skip
            vm.expectRevert();
            c.Collect(collectAmt);
        }

        // After collect, sum of reported balances should never exceed actual Ether in contract
        uint256 bal1_after = c.balances(caller1);
        uint256 bal2_after = c.balances(caller2);
        uint256 sumBalances = bal1_after + bal2_after;
        uint256 contractBalance = address(c).balance;

        // General invariant: sum of user balances <= contract balance
        // The reference ensures no overflow can inflate balances; the buggy one can.
        assertTrue(sumBalances <= contractBalance, "Sum of balances exceeds contract ETH balance");
    }
}

