pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        // Restrict inputs to avoid revert in Collect (minSum set, caller has balance >= minSum and >= collectAmount)
        vm.assume(minSum > 0 && minSum <= type(uint256).max);
        c.SetMinSum(minSum);
        c.Initialized();

        // Assume caller can deposit a reasonable amount
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Ensure caller's balance >= minSum and >= collectAmount
        uint256 callerBalance = c.balances(caller);
        vm.assume(collectAmount <= callerBalance && callerBalance >= minSum);
        vm.assume(collectAmount > 0);

        // Collect
