        c.Collect(collectAmount);

        // After Collect, caller's balance should be original deposit minus collectAmount (no overflow can increase it)
        uint256 remainingBalance = c.balances(caller);
        // General rule: caller's balance after Collect is exactly depositAmount - collectAmount (no overflow increase)
        assertTrue(remainingBalance == depositAmount - collectAmount, "Balance after Collect should be deposit minus collect");
