pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        // Precondition: depositAmount is not extremely large to avoid overflow before deposit
        vm.assume(depositAmount <= type(uint256).max / 2);
        // Setup: initialize contract, set MinSum, and fund caller
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();
        // Record contract balance before collect
        uint256 balanceBeforeCollect = address(c).balance;
        // Read caller's balance after deposit
        uint256 callerBalanceBeforeCollect = c.balances(caller);
        // Perform Collect if possible, but we allow revert (typical difference: reference reverts if overflow in Deposit, mutant doesn't)
        // To test the rule: after Collect, the sum of balances <= contract ether balance
        // Actually we need to bound collectAmount to be <= depositAmount to avoid revert due to insufficient balance in reference
        vm.assume(collectAmount <= callerBalanceBeforeCollect);
        vm.prank(caller);
        (bool successCollect, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        // If Collect succeeded, then we can check the invariant
