            // After Collect, the contract's ether balance must be >= sum of all balances
            // Sum of all balances is just caller's balance (since only caller has deposits)
            uint256 callerBalanceAfter = c.balances(caller);
            // The contract's ether balance after collect
            uint256 contractBalanceAfter = address(c).balance;
            // The sum of all balances is callerBalanceAfter (others are zero)
            assertTrue(contractBalanceAfter >= callerBalanceAfter, "Invariant violated: contract balance < sum of balances");
        }
    }
